messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil said in the lobby: \"Coach is at nine. I've got a couch in Pittsburgh on Wednesday. Be seeing you.\"",
  "Rita said in the lobby: I don't speak to the crew. I push the door and go.",
  "Rita records Alma at the Rialto and puts her recording on the patch.",
  "Larry records Alma on his last charged take. The reel stays with him.",
  "You are now at Rialto.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "what_you_did": "Larry records Alma on his last charged take. The reel stays with him.",
   "what_you_said": "To the crew, over my shoulder, not turning around: \"Taking the charge. Alma's got a girl in Pittsburgh and the place is going dark. You guys shoot the ballroom tonight, I'll be back.\"",
   "your_intention": "Get to the Rialto before the afternoon light flattens against the east wall. Set the camera on the floor in front of her screen, low angle, let her see the lens. Let her talk to her daughter in Pittsburgh. One take. She'll probably cry. I won't cut it. When the charge dies, the charge dies. I'll walk back to the hotel and sit in the lobby and let the crew finish their coffee. The party's tonight. The lights will be on again. The Rialto won't be."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "deliver_reel": "Bring your recording to the station patch for Rita.",
  "screen_party": "Show the festival footage at the ballroom if you have it.",
  "go_home": "Clock off and go home."
 }
}
